C("t13", D_, "عرّف النقض (الإجمالي).", "إبطال الدليل بعد تمامه متمسكاً بشاهد يدل على عدم استحقاقه للاستدلال به (ص ٥١).")
C("t13", D_, "عرّف الشاهد.", "ما يدل على فساد الدليل، للتخلف أو لاستلزامه محالاً (ص ٥٢).")
C("t13", Q_, "ما وجها الفساد اللذان يدل عليهما الشاهد؟", "١. التخلف: وجود الدليل مع عدم المدلول. ٢. لزوم المحال: كالدور والتسلسل واجتماع النقيضين (ص ٥١ - ٥٢).")
C("t13", M_, "مثّل للنقض بالتخلف.", "«الآية تدل على الوجوب لأنها أمر وكل أمر للوجوب»، فيُنقض بـ﴿فَكَاتِبُوهُمْ﴾: أمر ولا يدل على الوجوب.")
C("t13", M_, "مثّل للنقض بلزوم المحال.", "«الحد له تعريف؛ لأنه تعريف وكل تعريف له تعريف»، فيُنقض بلزوم التسلسل.")
C("t13", H_, "لماذا عدل المصنف عن التعريف المشهور للنقض «تخلّف الحكم عن الدليل»؟", "لأن النقض لا يختص بالتخلف بل يكون بلزوم المحال أيضاً، ولأن النقض صفة الناقض والتخلف صفة الحكم (ص ٥٢).")
C("t13", F_, "ما الفرق بين إطلاق «النقض» على المنع وعلى النقض الإجمالي؟", "المنع لا يسمى نقضاً إلا مقيداً بـ«التفصيلي»، أما الإجمالي فيطلق عليه النقض مطلقاً ومقيداً (ص ٥٢).")
# المعارضة
C("t14", D_, "عرّف المعارضة.", "إقامة الدليل على خلاف ما أقام الدليل عليه الخصم (ص ٥٣).")
C("t14", Q_, "ما الأسئلة المسموعة الواردة على دليل المعلل؟", "ثلاثة: المنع، والنقض، والمعارضة (ص ٥٣).")
C("t14", Q_, "اذكر أقسام المعارضة مع ضابط كل قسم.", "بالقلب: اتحاد الدليلين مادة وصورة. بالمثل: اتحادهما صورة فقط. بالغير: لا اتحاد (ص ٥٤ - ٥٥).")
C("t14", F_, "ما الفرق بين المعارضة بالقلب والمعارضة بالمثل؟", "في القلب يتحد الدليلان مادة وصورة، وفي المثل يتحدان صورة فقط وتختلف المادة (ص ٥٤ - ٥٥).")
C("t14", M_, "مثّل للمعارضة بالقلب.", "الحنفي: مسح الرأس ركن فلا يكفي أقل ما يطلق عليه اسم المسح كغسل الوجه. الشافعي: المسح ركن فلا يقدّر بالربع كغسل الوجه (ص ٥٦).")
C("t14", M_, "مثّل للمعارضة بالمثل.", "المعلل: العالم محتاج إلى المؤثر وكل محتاج حادث. المعارض: العالم مستغنٍ عن المؤثر وكل مستغنٍ قديم (ص ٥٦).")
C("t14", M_, "مثّل للمعارضة بالغير.", "المعارض: لو كان العالم حادثاً لما كان مستغنياً، لكنه مستغنٍ فليس بحادث (ص ٥٦).")
C("t14", H_, "ما المراد بـ«الخلاف» في تعريف المعارضة؟", "ما ينافي مدعى الخصم: نقيضه أو مساوي نقيضه أو الأخص منه، لا ما يغايره مطلقاً (ص ٥٣).")
C("t14", H_, "أين توجد المعارضة بالقلب؟", "في المغالطات العامة الورود (لا في الدلائل العقلية الصرفة)، وفي القياسات الفقهية أيضاً (ص ٥٥).")
# التوجيه والغصب
C("t15", D_, "عرّف التوجيه.", "أن يوجه المناظر كلامه (منعاً أو نقضاً أو معارضة) إلى كلام الخصم (ص ٥٧).")
C("t15", D_, "عرّف الغصب، وما حكمه؟", "أخذ منصب الغير، وهو غير مستحسن، ويجوز عند الضرورة (ص ٥٧).")
C("t15", M_, "مثّل للغصب.", "ناقل نقل عن أبي حنيفة ومحمد أن المظاهر إذا جامع في خلال صيام الكفارة استأنف، ثم استدل بآية ﴿مِن قَبْلِ أَن يَتَمَاسَّا﴾، فأخذ منصب المدعي (ص ٥٧).")
# أجزاء البحث
C("t16", Q_, "ما أجزاء البحث الثلاثة؟ عرّف كلاً منها.", "مبادئ: تعيين المدعى. أوساط: الدلائل. مقاطع: المقدمات التي ينتهي إليها البحث من الضروريات والظنيات المسلّمة عند الخصم (ص ٥٧ - ٥٨).")
C("t16", H_, "لماذا سُميت الدلائل «أوساطاً»؟", "لتأخرها عن تعيين المدعى وتقدمها على ما ينتهي إليه البحث (ص ٥٨).")
C("t16", M_, "مثّل للمقاطع.", "بطلان الدور والتسلسل واجتماع النقيضين؛ فإذا انتهى البحث إليها انقطع وتم (ص ٥٨).")
C("t16", H_, "ما الواجب على السائل أولاً في المبادئ؟", "أن يطالب ما أمكنه من تعريف مفردات المدعى وتعيين البحث، إن لم تكن معلومة له، كقوله: ما النية؟ ما الشرط؟ ما الوضوء؟ (ص ٥٨).")
C("t16", H_, "هل يتوجه المنع على المعلل وهو في تعريف الأقوال والتحرير؟", "لا؛ لأنه ذكر القول حكاية لا ادعاء، إلا إذا أخطأ في النقل أو عرّف تعريفاً غير جامع أو غير مانع (ص ٥٩).")
# البحث الأول
C("t17", D_, "ما المراد بالترتيب الطبعي للبحث؟", "الترتيب الذي تقتضي طبيعة البحث أن يكون عليه في التقديم والتأخير (ص ٥٩ - ٦٠).")
C("t17", Q_, "رتّب خطوات المناظرة كما في البحث الأول.", "استفسار ثم بيان، ثم المؤاخذة بتصحيح النقل أو التنبيه أو الدليل، ثم منع أو نقض أو معارضة، ثم جواب المعلل (ص ٦٠ - ٦٢).")
C("t17", Q_, "بماذا يجيب المعلل عن المنع؟", "بإبطال السند بعد إثبات التساوي، أو بإثبات المقدمة الممنوعة مع التعرض لما تمسك به المانع (ص ٦١).")
C("t17", Q_, "بماذا يجيب المعلل عن النقض والمعارضة؟", "بالمنع أو النقض أو المعارضة؛ لأنه يصير سائلاً، ويجوز في الكل التغيير أو التحرير (ص ٦٢).")
C("t17", H_, "لماذا لا ينفع إبطال السند إلا بعد إثبات التساوي؟", "لأن انتفاء أحد المتساويين يدل على انتفاء الآخر، أما انتفاء الأخص فلا يستلزم انتفاء الأعم (ص ٦١ - ٦٢).")
C("t17", H_, "لماذا لا يكثر نفع الأسئلة على التنبيه؟", "لأنه لم يُقصد به إثبات الدعوى، فهي بديهية مستغنية عن الإثبات فلا يقدح السؤال في ثبوتها (ص ٦٣).")
C("t17", F_, "ما الفرق بين التغيير والتحرير في الجواب؟", "التغيير: تغيير الدعوى أو الدليل أو المقدمة الممنوعة. التحرير: بيان المراد من الكلام بحيث لا يرد عليه شيء (ص ٦٢، ٥٩).")
# البحث الثاني
C("t18", Q_, "ما الدعاوي الضمنية في التعريف الحقيقي؟", "أن هذا المذكور حدّ له، وأن الجزء الأول جنس، والثاني فصل (ص ٦٣ - ٦٤).")
C("t18", Q_, "كيف يتوجه كل من المنع والنقض والمعارضة على التعريف؟", "المنع: لا نسلّم أنه حدّ أو جنس أو فصل. النقض: ببيان الاختلال في طرده (ليس بمانع) أو عكسه (ليس بجامع). المعارضة: بحدّ آخر يعترف به الحاد (ص ٦٤).")
C("t18", H_, "لماذا استُصعب الجواب عن المنع في الحدود الحقيقية؟", "لتوقفه على الاطلاع على الذاتيات، وهو في غاية الصعوبة كما صرح ابن سينا (ص ٦٥).")
C("t18", Q_, "بماذا يُدفع المنع عن الحدود الاعتبارية واللفظية؟", "بمجرد نقل من أهل الاصطلاح أو اللغة، أو بوجه استعمال، أو ببيان إرادة (ص ٦٦).")
C("t18", H_, "هل إطلاق المنع والنقض والمعارضة على أسئلة التعريف حقيقة أم مجاز؟", "بطريق الاستعارة (المصرّحة)، ويحتمل الحقيقة (ص ٦٦).")
C("t18", H_, "كيف شبّه الشارح الحادّ؟", "بالنقاش: الحادّ ينقش في الذهن صورة معقولة، والنقاش ينقش في اللوح صورة محسوسة، فلا يتوجه المنع إلا على الحكم الضمني (ص ٦٥).")
# البحث الثالث
C("t19", H_, "لماذا لا يتوجه المنع حقيقة على النقل والدعوى؟", "لأن المنع طلب الدليل على مقدمة معينة، ولا مقدمة دليل فيهما؛ وإطلاقه عليهما مجاز عن طلب التصحيح أو الدليل (ص ٦٦ - ٦٧).")
C("t19", H_, "ما حكم طلب التصحيح والتنبيه والدليل على المعلوم؟", "لا يجوز، إلا إذا كان المقصود معلوميته بطريق آخر (ص ٦٨).")
C("t19", H_, "هل يلزم من بطلان الدليل بطلان المدلول؟ ولماذا؟", "لا؛ لجواز أن يكون للمدلول الواحد أدلة شتى، فإذا بطل الدليل فلا منصب للمعلل إلا التغيير (ص ٦٩).")
C("t19", H_, "متى يتوجه المنع على المنقول (على القول الآخر)؟", "إذا التزم الناقل صحته، فيصير مدعياً لا ناقلاً (ص ٦٧).")
# البحث الرابع
C("t20", H_, "ما حكم منع المعلوم مطلقاً؟", "مكابرة لا تُسمع (ص ٦٩).")
C("t20", H_, "ما حكم منع البديهي الخفي ومقدمة التنبيه؟", "يجوز تجوّزاً؛ لأن المنع حقيقة طلب الدليل على مقدمة معينة من الدليل (ص ٦٩ - ٧٠).")
C("t20", H_, "ما حكم منع مقدمة ضمنية؟ ولماذا؟", "جائز؛ لأن المقدمة «ما يتوقف عليه صحة الدليل» وهي أعم من جزئه (ص ٦٩).")
C("t20", D_, "ما المقصود بالمنع على تقدير التسليم؟", "أن يمنع مقدمة ثم يقول: وإن سلّمناها فلا نسلّم المقدمة الأخرى، في الترديدات أو غيرها (ص ٧٠).")
C("t20", F_, "ما معنى «على تفاوت» في المنع على تقدير التسليم؟", "قد يكون التسليم واجباً إذا كان المنع الثاني مبنياً على تسليم الأول، وقد يكون استحساناً إذا لم يكن مبنياً عليه (ص ٧٠ - ٧١).")
C("t20", H_, "متى لا يضر المنع المعلل؟ وماذا يقول؟", "إذا كان انتفاء المقدمة الممنوعة مستلزماً للمطلوب، فيردد: إن ثبتت تم الدليل، وإلا فالدعوى ثابتة أيضاً (ص ٧١ - ٧٢).")
C("t20", F_, "ما حكم توقف المانع حتى يتم المعلل دليله في المنع، وفي النقض والمعارضة؟", "في المنع مستحسن (وقيل بخلافه)، وفي النقض والمعارضة واجب بالاتفاق (ص ٧٣).")
C("t20", D_, "عرّف الحلّ.", "تعيين موضع الغلط الذي نشأ من سوء الفهم (ص ٧٤).")
C("t20", F_, "ما الفرق بين الحلّ والمنع؟", "يشتركان في التعرض لمقدمة معينة، فيندرج الحل في المنع؛ ويفترقان في أن الحل لا يُقصد به طلب الدليل بل تعيين موضع الغلط (ص ٧٤).")
# البحث الخامس
C("t21", H_, "لماذا لا يكون السند الصحيح أعم؟", "لأنه ملزوم لخفاء المقدمة ومقوٍّ للمنع، والأعم لا يكون ملزوماً ومقوياً (ص ٧٤ - ٧٥).")
C("t21", H_, "ما معنى قولهم: «ما من مقدمة إلا يمكن منعها مستنداً بما ذهب إليه السوفسطائية»؟ وما موقف الحكيم؟", "كل مقدمة يمكن منعها بسند من مذهب نفاة الحقائق، لكن الحكيم يعدّ ذلك مكابرة غير مسموعة (ص ٧٥).")
C("t21", H_, "ما حكم البحث في مقوّي السند؟", "لا يحسن؛ لأن إبطاله لا يوجب إثبات المقدمة الممنوعة، ولا يلزم المانع إثباته (ص ٧٥ - ٧٦).")
C("t21", H_, "ما حكم إثبات السائل منافي المقدمة قبل دليلها؟ وبعده؟", "قبله لا يجوز للزوم الغصب من غير ضرورة، وبعده يجوز ويسمى مناقضة على سبيل المعارضة (ص ٧٦).")
C("t21", D_, "عرّف السند الأخص.", "أن يتحقق المنع (انتفاء المقدمة الممنوعة) مع انتفائه أيضاً، من غير عكس (ص ٧٦).")
C("t21", D_, "عرّف السند المساوي.", "ألا ينفك أحدهما عن الآخر في صورتي التحقق والانتفاء (ص ٧٧).")
C("t21", H_, "هل السند الأعم سند حقيقة؟", "لا، ليس بسند في الحقيقة؛ لأنه لا يقوّي المنع حقيقة (ص ٧٧).")
C("t21", F_, "ما الفرق بين السند الأخص والمساوي والأعم من حيث نفع إبطاله للمعلل؟", "إبطال المساوي يُثبت المقدمة، وإبطال الأخص لا يكفي، والأعم ليس سنداً في الحقيقة وإن أفاد إبطاله المطلق منه (ص ٦٢، ٧٧).")
# البحث السادس
C("t22", F_, "ما الفرق بين النقض والمناقضة من جهة الشاهد؟ ولماذا؟", "النقض لا يُسمع بلا شاهد، والمناقضة تُسمع؛ لأن منع مقدمة معينة يعرّف المعلل موضع الخلل، أما منع الدليل جملة فيحيّره (ص ٧٨).")
C("t22", Q_, "اذكر طرق دفع الشاهد الخمسة.", "منع جريان الدليل، منع التخلف، إظهار أن التخلف لمانع، منع استلزام المحال، منع الاستحالة (ص ٧٩ - ٨٠).")
C("t22", D_, "ما الطرد والعكس في التعريف؟", "الطرد: التلازم في الثبوت (كلما صدق الحد صدق المحدود) = المانعية. العكس: التلازم في الانتفاء (كلما لم يصدق الحد لم يصدق المحدود) = الجامعية (ص ٧٩).")
C("t22", H_, "لماذا سُمي القدح في طرد التعريف وعكسه نقضاً؟", "بطريق الاستعارة المصرّحة؛ لمشابهته النقض الإجمالي في قولنا: هذا التعريف ليس بصحيح لاستلزامه دخول غير المحدود أو خروج فرد منه (ص ٧٩).")
C("t22", M_, "مثّل لدفع الشاهد بمنع جريان الدليل.", "الخارج النجس من غير السبيلين حدث. نُقض بما لم يسِل، فنقول: لا نسلّم أنه «خارج» بل «بادٍ» (ص ٨٠).")
C("t22", M_, "مثّل لدفع الشاهد بإظهار أن التخلف لمانع.", "دم صاحب الجرح السائل نجس خارج ولم ينقض الطهارة في الوقت؛ فالحكم موجود ولم يظهر لمانع العذر (ص ٨٠).")
C("t22", H_, "هل يحتاج الشاهد نفسه إلى دليل؟", "قد يحتاج إلى دليل إن كان نظرياً غير معلوم للمعلل، أو إلى تنبيه إن كان بديهياً غير أوّلي (ص ٧٩).")
# البحث السابع
C("t23", Q_, "ما أحوال نفي المدلول الثلاث وأسماؤها؟", "بلا دليل: مكابرة. بدليل قبل إقامة المدعي دليله: غصب. بدليل بعدها: معارضة (ص ٨١ - ٨٢).")
C("t23", H_, "هل يشترط في المعارضة تسليم دليل الخصم؟", "الاشتراط أشهر، وعدمه أظهر؛ لأن تسليم الدليل يستلزم تصديق مدلوله فيلزم تصديق المتنافيين، لكن يلزم عليه حصر وظيفة السائل في المنع والنقض (ص ٨٢).")
C("t23", D_, "ما «المعارضة فيها النقض»؟", "المعارضة في القطعيات، وهي راجعة إلى النقض لامتناع اجتماع قطعيين متنافيين (ص ٨٣).")
C("t23", H_, "لماذا سُميت «معارضة فيها النقض» لا «نقضاً فيه معارضة»؟", "لأن المعارضة صريحة والنقض ضمني، والضمنيات لا تُعتبر في التسمية (ص ٨٣).")
C("t23", F_, "ما العلاقة بين «المعارضة فيها النقض» و«المعارضة بالقلب»؟", "قيل: أخوان متشاركان في الحقيقة، والتغاير بالاعتبار: باعتبار قلب دليل المستدل شاهداً عليه = قلب، وباعتبار تضمنها النقض = معارضة فيها النقض (ص ٨٣).")
C("t23", Q_, "ما الأقسام التي تردد بعضهم في جوازها (التتمة)؟ وما الحق؟", "المعارضة على المعارضة، والمعارضة بالبداهة وبالدليل على البديهي وعلى المبيّن بداهته بالدليل. والحق جوازها (ص ٨٤ - ٨٥).")
C("t23", H_, "إذا عورض البديهي بالبرهان فأيهما أحق؟", "البرهان أحق بالاعتبار، كما أن العقلي أحق من النقلي، إلا إذا أفاد النقلي القطع كالمحكم والمتواتر (ص ٨٥).")
C("t23", Q_, "ما الذي يتناوله «خلاف المدلول» في المعارضة (التبصرة)؟", "النقيض، والأخص من النقيض، والمساوي للنقيض (ص ٨٥).")
C("t23", M_, "مثّل للمعارضة بالأخص من النقيض.", "الشافعي: الترتيب في الوضوء فرض. الحنفي: هو سنة؛ والسنة أخص من «ليس بفرض» (ص ٨٥).")
# البحث الثامن
C("t24", D_, "ما «المناقضة على سبيل المعارضة» و«على سبيل النقض»؟", "أن تُعارض المقدمة المعينة أو يُنقض دليلها بعد إقامة المعلل الدليل عليها (ص ٨٥ - ٨٦).")
C("t24", H_, "لماذا سُمي نقض المقدمة ومعارضتها «مناقضة»؟", "لوجود معنى المنع فيه بالنسبة إلى الدليل الأصلي الذي هي مقدمته؛ والأولى: لمشاركته المنع في أنه كلام على المقدمة (ص ٨٦).")
C("t24", H_, "كيف تُنقض المقدمة بضمها إلى مقدمة حقة؟", "تُضم إلى مقدمة حقة مسلّمة فيلزم من اجتماعهما محال، فيظهر فسادها لأن الحقة لا تستلزم محالاً (ص ٨٧).")
# البحث التاسع والتكملة
C("t25", H_, "لماذا لا يحسن النقض والمعارضة على المستدل المشكّك المغالط؟", "لأنه لا يدعي صحة مقاله بل غرضه إيقاع الشك، والشك باقٍ بعدهما فلا ينفعان؛ وتحسن المناقضة (ص ٨٧).")
C("t25", Q_, "ما ترتيب الأسئلة الثلاثة إذا اجتمعت؟", "عند المصنف: المنع أولاً، والمعارضة آخراً. وقيل: النقض ثم المناقضة، وهما قبل المعارضة (ص ٨٨).")
C("t25", H_, "لماذا كان المنع أحق بالتقديم؟", "لأن في النقض والمعارضة عدولاً من السائل عن حقه، إذ حقه أن يستفسر ولا يتعرض لدليل المعلل بالإفساد (ص ٨٨).")
C("t25", H_, "لماذا كانت المعارضة أحق بالتأخير؟", "لأنها قدح في صحة الدليل ضمناً (ص ٨٨).")
C("t25", Q_, "ما الأسئلة الخمسة التي نُقض بها حصر الأسئلة في الثلاثة؟", "القدح لعدم الاستلزام، أو للاحتياج إلى مقدمة، أو لاستدراك مقدمة، والمصادرة على المطلوب، ومنع ما يلزم صحة الدليل (ص ٨٨ - ٨٩).")
C("t25", H_, "كيف أُجيب عن نقض الحصر؟", "الأول والثاني والرابع: إن كانت بشاهد فنقض وإلا فمكابرة. الثالث: لا ينافي غرض المناظر. الخامس: داخل في المنع بتفسير المقدمة بما يتوقف عليه صحة الدليل (ص ٨٩).")
C("t25", D_, "ما المصادرة على المطلوب؟", "أن يكون الدليل أو جزؤه لا يتم ولا يصح إلا إذا صح المدلول أو جزؤه (ص ٨٩).")
C("t25", F_, "لماذا قيل: المعارضة أقوى من النقض؟", "لأن المعارضة نفي المدلول فيلزم منه نفي الدليل (نفي اللازم يستلزم نفي الملزوم)، والنقض نفي الدليل ولا يلزم منه نفي المدلول (ص ٨٨).")
# الخاتمة والوصية
C("t26", H_, "بماذا تتعلق المناظرة كلها؟", "بالأحكام الخبرية، صريحة كما في الدعاوي، أو ضمنية كما في التعريفات (ص ٩٠).")
C("t26", H_, "طلب تصحيح نقل حديث إنشائي كـ«كن في الدنيا كأنك غريب»: هل هو مناظرة في الإنشاء؟", "لا؛ إنما يُطلب تصحيح كونه قول النبي ﷺ، وهذا خبر لا إنشاء (ص ٩١).")
C("t26", H_, "لماذا رُدّ القول بتصور المناظرة بلا حكم؟", "لأنه هدم لحد المناظرة المنقول عن واضع الفن، وتكثير لقواعد البحث من غير ضرورة، والتقليل أليق بالضبط (ص ٩١).")
C("t27", H_, "ما وصية المصنف في الاستعجال؟", "لا يحسن الاستعجال في البحث قبل الفهم، وفي عدمه فوائد للمعلل والسائل (ص ٩١).")
C("t27", H_, "ما معنى «لا يتكلم في اليقيني بوظائف الظني ولا بالعكس»؟", "لا يعارض القطعي كالقرآن بأمارة ظنية كالقياس، ولا يعترض على الظني باحتمال الخلاف كما في مثال السقمونيا (ص ٩٢).")
C("t27", Q_, "اذكر آداب المناظر التي ذكرها الفخر الرازي.", "تجنب الاختصار المخل والتطويل الممل والألفاظ الغريبة والجمل المحتملة وما لا دخل له، وألا يضحك أو يرفع صوته، وأن يحترز عن المهيب، وألا يحتقر خصمه (ص ٩٢ - ٩٣).")
C("t27", Q_, "ما زيادات الشارح على آداب المناظر؟", "ألا يقصد إسكات الخصم سريعاً، وأن يجلس جلسة الفقراء لا الأمراء، وألا يكون جائعاً أو عطشان جداً أو ممتلئاً (ص ٩٣).")
C("t27", M_, "مثّل للتكلم في الظني بوظائف اليقيني.", "الطبيب: السقمونيا مسهل للصفراء بالتتبع. السائل: يجوز أن يكون فرد منه غير مسهل. فلا يفيد؛ لأن غرض الطبيب الظن (ص ٩٢).")
